import{c as t,Q as a,j as r,m as o}from"./chunks/framework.DOi4mjdC.js";const M=JSON.parse('{"title":"基础知识","description":"","frontmatter":{},"headers":[{"level":1,"title":"基础知识","slug":"基础知识"}],"relativePath":"guide/算子实践参考/SIMD与SIMT混合算子实现/基础知识.md","filePath":"guide/算子实践参考/SIMD与SIMT混合算子实现/基础知识.md"}'),I={name:"guide/算子实践参考/SIMD与SIMT混合算子实现/基础知识.md"};function n(c,e,l,S,i,s){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="基础知识" tabindex="-1">基础知识 <a class="header-anchor" href="#基础知识" aria-label="Permalink to &quot;基础知识&quot;">​</a></h1><p>本节内容为使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Reg%E7%9F%A2%E9%87%8F%E8%AE%A1%E7%AE%97.md" target="_blank" rel="noreferrer">Reg矢量计算API</a>和<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SIMT-API.md" target="_blank" rel="noreferrer">SIMT API</a>进行SIMD与SIMT混合编程的指导。</p><p>在<a href="./../../编程指南/硬件实现/基本架构.html#li6862114311118">Vector Core</a>中，SIMT单元和SIMD单元共享片上存储，因此可以利用片上存储Unified Buffer完成SIMD与SIMT混合编程，具体硬件架构的介绍请参考<a href="./../../编程指南/高级编程/硬件实现/架构规格/NPU架构版本3510.html">NPU架构版本3510</a>。在进行后续内容的学习前，请先了解SIMD与SIMT混合编程的编程模型：<a href="./../../编程指南/高级编程/高级AI-Core编程模型/SIMD与SIMT混合编程.html">SIMD与SIMT混合编程</a>。</p><p><a href="./../../编程指南/编程模型/AI-Core-SIMD编程/SIMD编程/Reg矢量计算编程.html">SIMD编程</a>提供了基于寄存器（Regbase）开发的Reg矢量计算API，Reg矢量计算API可以直接操作Vector Core中的SIMD寄存器，API单次处理的数据量上限等于寄存器的大小，通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/GetVecLen.md" target="_blank" rel="noreferrer">GetVecLen</a>接口获取该值。在算子实现中，需要多次调用Reg矢量计算API完成对单核数据的处理。</p><p>与SIMD编程不同的是，在SIMT编程中Global Memory上的数据可以被直接读取和使用。SIMT编程常通过组织线程的层次结构来实现数据的切分，使用threadIdx等<a href="./../../编程指南/语言扩展层/SIMT-BuiltIn关键字.html">SIMT BuiltIn关键字</a>计算线程应处理的数据索引，完成索引对应数据的计算，从而将函数实现简化为标量计算。</p>',5)])])}const _=t(I,[["render",n]]);export{M as __pageData,_ as default};
